// ─────────────────────────────────────────────────────────────────────────────
// Wall — event kinds, filter chips and primary navigation.
// Single source of truth for the project activity feed (src/components/wall/*).
//
// The wall is codx-junior's own activity stream. It uses the project branding
// (the codx-junior logo) and daisyUI theme tokens only — no third-party brand
// names, logos or copy are referenced anywhere.
// ─────────────────────────────────────────────────────────────────────────────

export const WALL_KINDS = {
  chat:   { label: 'Chat',         icon: 'fa-solid fa-comment',           color: 'text-info' },
  code:   { label: 'Changes',      icon: 'fa-solid fa-code',              color: 'text-success' },
  kanban: { label: 'Task',         icon: 'fa-brands fa-trello',           color: 'text-codx-primary' },
  commit: { label: 'Commit',       icon: 'fa-solid fa-code-commit',       color: 'text-success' },
  pr:     { label: 'Pull request', icon: 'fa-solid fa-code-pull-request', color: 'text-secondary' },
  meet:   { label: 'Meet',         icon: 'fa-solid fa-video',             color: 'text-error' },
  index:  { label: 'Knowledge',    icon: 'fa-solid fa-database',          color: 'text-warning' },
  wiki:   { label: 'Wiki',         icon: 'fa-solid fa-graduation-cap',    color: 'text-success' },
  system: { label: 'System',       icon: 'fa-solid fa-circle-info',       color: 'text-base-content/60' },
  user:   { label: 'Joined',       icon: 'fa-solid fa-user-plus',         color: 'text-info' }
}

// Kind filter chips, in display order ('all' first)
export const WALL_FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'chat', label: 'Chats' },
  { key: 'code', label: 'Changes' },
  { key: 'kanban', label: 'Tasks' },
  { key: 'pr', label: 'Pull requests' },
  { key: 'meet', label: 'Meets' },
  { key: 'index', label: 'Knowledge' },
  { key: 'wiki', label: 'Wiki' },
  { key: 'system', label: 'System' }
]

// Primary navigation (desktop rail + mobile menu)
export const WALL_NAV = [
  { key: 'home', label: 'Home', icon: 'fa-solid fa-house' },
  { key: 'explore', label: 'Explore', icon: 'fa-solid fa-magnifying-glass' },
  { key: 'notifications', label: 'Notifications', icon: 'fa-solid fa-bell' },
  { key: 'messages', label: 'Messages', icon: 'fa-solid fa-envelope' },
  { key: 'bookmarks', label: 'Bookmarks', icon: 'fa-solid fa-bookmark' },
  { key: 'profile', label: 'Profile', icon: 'fa-solid fa-user' }
]

export function kindConfig(kind) {
  return WALL_KINDS[kind] || WALL_KINDS.system
}

import moment from 'moment'

// ─────────────────────────────────────────────────────────────────────────────
// Wall — pure helpers that turn codx-junior store data into feed posts.
//
// Everything here is a side-effect-free function so the mapping stays easy to
// reason about (and to unit-test) independently from the components.
// ─────────────────────────────────────────────────────────────────────────────

// Deterministic 0..n hash — used to pick a stable avatar colour per account
export function seedIndex(str) {
  let h = 0
  const s = String(str || '')
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0
  return h
}

// daisyUI background classes used as deterministic avatar fallbacks
const AVATAR_CLASSES = ['bg-primary', 'bg-secondary', 'bg-accent', 'bg-info', 'bg-success', 'bg-warning']

export function avatarClass(seed) {
  return AVATAR_CLASSES[seedIndex(seed) % AVATAR_CLASSES.length]
}

export function initials(name) {
  const words = String(name || '').trim().split(/\s+/).filter(Boolean)
  if (!words.length) return '?'
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words[1][0]).toUpperCase()
}

export function formatRelative(iso) {
  const d = moment(iso)
  return d.isValid() ? d.fromNow() : ''
}

export function formatTime(iso) {
  const d = moment(iso)
  return d.isValid() ? d.format('MMM D, YYYY · HH:mm') : ''
}

export function formatCount(n) {
  n = Number(n) || 0
  if (n < 1000) return String(n)
  if (n < 1000000) return (n / 1000).toFixed(n < 10000 ? 1 : 0).replace(/\.0$/, '') + 'K'
  return (n / 1000000).toFixed(1) + 'M'
}

// The account used whenever an event has no author of its own
export function botAccount() {
  return { id: 'codx-junior', name: 'codx-junior', handle: 'codx-junior', avatar: null, verified: true, type: 'bot' }
}

export function meAccount(currentUser) {
  return {
    id: '__me',
    name: currentUser?.name || currentUser?.username || 'You',
    handle: currentUser?.username || 'you',
    avatar: currentUser?.avatar || null,
    verified: false,
    type: 'me'
  }
}

// Build the accounts referenced by the feed (current user + bot + users + projects)
export function buildAccounts({ currentUser = null, users = [], projects = [] } = {}) {
  const accounts = { __me: meAccount(currentUser), 'codx-junior': botAccount() }
  const userList = users || []
  const projectList = projects || []

  userList.forEach(u => {
    const id = u?.id || u?.username || u?.userName
    if (!id || accounts[id]) return
    accounts[id] = {
      id,
      name: u.name || u.username || u.userName || 'User',
      handle: u.username || u.userName || id,
      avatar: u.avatar || null,
      verified: false,
      type: 'user'
    }
  })

  projectList.forEach(p => {
    if (!p?.project_id || accounts[p.project_id]) return
    accounts[p.project_id] = {
      id: p.project_id,
      name: p.project_name,
      handle: p.project_name,
      avatar: p.project_icon || null,
      verified: true,
      type: 'project'
    }
  })

  return accounts
}

const EMPTY_COUNTS = { replies: 0, reposts: 0, likes: 0, views: 0 }

function postContext(chat, project) {
  if (chat?.board) return { label: chat.board, icon: 'fa-brands fa-trello' }
  if (project?.project_name) return { label: project.project_name, icon: 'fa-solid fa-cube' }
  return null
}

function postAttachment(chat) {
  if (!chat) return null
  if (chat.pr_view?.from_branch) {
    return {
      type: 'pr',
      title: chat.pr_view.title || chat.name,
      from: chat.pr_view.from_branch,
      to: chat.pr_view.to_branch
    }
  }
  if (chat.file_list?.length) {
    return { type: 'code', files: chat.file_list.map(path => ({ path })) }
  }
  if (chat.board || chat.column) {
    return { type: 'board', board: chat.board, to: chat.column || chat.status, task: chat.name }
  }
  return null
}

function postKind(chat) {
  if (chat?.pr_view?.from_branch) return 'pr'
  if (chat?.file_list?.length) return 'code'
  if (chat?.board || chat?.column) return 'kanban'
  return 'chat'
}

// Turn a chat (a project activity item) into a feed post
export function chatToPost(chat, project) {
  if (!chat) return null
  const messages = chat.messages || []
  const last = messages[messages.length - 1] || {}
  const isBot = last.role === 'assistant'
  const text = String(last.content || chat.name || 'Activity').replace(/\s+/g, ' ').trim()
  return {
    id: `chat-${project?.project_id || 'na'}-${chat.id || chat.doc_id || text.slice(0, 16)}`,
    kind: postKind(chat),
    authorId: isBot ? 'codx-junior' : (last.user || '__me'),
    createdAt: last.timestamp || last.created_at || chat.updated_at || chat.lastMessageAt || new Date().toISOString(),
    text: text.slice(0, 500),
    context: postContext(chat, project),
    attachment: postAttachment(chat),
    counts: { ...EMPTY_COUNTS, views: messages.length },
    chatId: chat.id,
    projectId: project?.project_id || null
  }
}

// Turn a live meet into a feed post
export function meetToPost(meet) {
  if (!meet?.meetId) return null
  return {
    id: `meet-${meet.meetId}`,
    kind: 'meet',
    authorId: meet.initiator || 'codx-junior',
    createdAt: meet.startedAt ? new Date(meet.startedAt).toISOString() : new Date().toISOString(),
    text: `Meeting started — ${meet.name || 'Meet'}`,
    context: { label: 'Meet', icon: 'fa-solid fa-video' },
    attachment: { type: 'meet', title: meet.name, participants: meet.participants || [] },
    counts: { ...EMPTY_COUNTS, views: (meet.participants || []).length },
    meetId: meet.meetId
  }
}

// Turn a UI notification into a feed post (used by the Notifications view)
export function notificationToPost(notification, index) {
  return {
    id: `notif-${index}-${notification?.ts || ''}`,
    kind: 'system',
    authorId: 'codx-junior',
    createdAt: new Date().toISOString(),
    text: notification?.text || '',
    context: null,
    attachment: null,
    type: notification?.type || 'info',
    counts: { ...EMPTY_COUNTS }
  }
}

// Assemble the feed from every source, newest first
export function buildPosts({ chats = [], meets = [], notifications = [], withNotifications = false } = {}) {
  const posts = []

  chats.forEach(({ chat, project }) => {
    const post = chatToPost(chat, project)
    if (post) posts.push(post)
  })

  meets.forEach(meet => {
    const post = meetToPost(meet)
    if (post) posts.push(post)
  })

  if (withNotifications) {
    notifications.forEach((n, ix) => posts.push(notificationToPost(n, ix)))
  }

  return posts.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
}

// Tab / kind / free-text filtering
export function filterPosts(posts, { tab = 'for-you', kind = 'all', query = '', following = [] } = {}) {
  let out = posts

  if (tab === 'following') {
    const set = new Set(following)
    out = out.filter(p => p.authorId === '__me' || p.authorId === 'codx-junior' || set.has(p.authorId))
  }

  if (kind && kind !== 'all') out = out.filter(p => p.kind === kind)

  const q = String(query || '').trim().toLowerCase()
  if (q) {
    out = out.filter(p =>
      String(p.text || '').toLowerCase().includes(q) ||
      String(p.context?.label || '').toLowerCase().includes(q))
  }

  return out
}

// ─────────────────────────────────────────────────────────────────────────────
// Wall — event kinds, filter chips and primary navigation.
// Single source of truth for the project activity feed (src/components/wall/*).
//
// The wall is codx-junior's own activity stream. It uses the project branding
// (the codx-junior logo) and daisyUI theme tokens only — no third-party brand
// names, logos or copy are referenced anywhere.
// ─────────────────────────────────────────────────────────────────────────────

export const WALL_KINDS = {
  chat:   { label: 'Chat',         icon: 'fa-solid fa-comment',           color: 'text-info' },
  code:   { label: 'Changes',      icon: 'fa-solid fa-code',              color: 'text-success' },
  kanban: { label: 'Task',         icon: 'fa-brands fa-trello',           color: 'text-codx-primary' },
  commit: { label: 'Commit',       icon: 'fa-solid fa-code-commit',       color: 'text-success' },
  pr:     { label: 'Pull request', icon: 'fa-solid fa-code-pull-request', color: 'text-secondary' },
  meet:   { label: 'Meet',         icon: 'fa-solid fa-video',             color: 'text-error' },
  index:  { label: 'Knowledge',    icon: 'fa-solid fa-database',          color: 'text-warning' },
  wiki:   { label: 'Wiki',         icon: 'fa-solid fa-graduation-cap',    color: 'text-success' },
  system: { label: 'System',       icon: 'fa-solid fa-circle-info',       color: 'text-base-content/60' },
  user:   { label: 'Joined',       icon: 'fa-solid fa-user-plus',         color: 'text-info' }
}

// Kind filter chips, in display order ('all' first)
export const WALL_FILTERS = [
  { key: 'all', label: 'All' },
  { key: 'chat', label: 'Chats' },
  { key: 'code', label: 'Changes' },
  { key: 'kanban', label: 'Tasks' },
  { key: 'pr', label: 'Pull requests' },
  { key: 'meet', label: 'Meets' },
  { key: 'index', label: 'Knowledge' },
  { key: 'wiki', label: 'Wiki' },
  { key: 'system', label: 'System' }
]

// Primary navigation (desktop rail + mobile menu)
export const WALL_NAV = [
  { key: 'home', label: 'Home', icon: 'fa-solid fa-house' },
  { key: 'explore', label: 'Explore', icon: 'fa-solid fa-magnifying-glass' },
  { key: 'notifications', label: 'Notifications', icon: 'fa-solid fa-bell' },
  { key: 'messages', label: 'Messages', icon: 'fa-solid fa-envelope' },
  { key: 'bookmarks', label: 'Bookmarks', icon: 'fa-solid fa-bookmark' },
  { key: 'profile', label: 'Profile', icon: 'fa-solid fa-user' }
]

export function kindConfig(kind) {
  return WALL_KINDS[kind] || WALL_KINDS.system
}

import moment from 'moment'

// ─────────────────────────────────────────────────────────────────────────────
// Wall — pure helpers that turn codx-junior store data into feed posts.
//
// Everything here is a side-effect-free function so the mapping stays easy to
// reason about (and to unit-test) independently from the components.
// ─────────────────────────────────────────────────────────────────────────────

// Deterministic 0..n hash — used to pick a stable avatar colour per account
export function seedIndex(str) {
  let h = 0
  const s = String(str || '')
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0
  return h
}

// daisyUI background classes used as deterministic avatar fallbacks
const AVATAR_CLASSES = ['bg-primary', 'bg-secondary', 'bg-accent', 'bg-info', 'bg-success', 'bg-warning']

export function avatarClass(seed) {
  return AVATAR_CLASSES[seedIndex(seed) % AVATAR_CLASSES.length]
}

export function initials(name) {
  const words = String(name || '').trim().split(/\s+/).filter(Boolean)
  if (!words.length) return '?'
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words[1][0]).toUpperCase()
}

export function formatRelative(iso) {
  const d = moment(iso)
  return d.isValid() ? d.fromNow() : ''
}

export function formatTime(iso) {
  const d = moment(iso)
  return d.isValid() ? d.format('MMM D, YYYY · HH:mm') : ''
}

export function formatCount(n) {
  n = Number(n) || 0
  if (n < 1000) return String(n)
  if (n < 1000000) return (n / 1000).toFixed(n < 10000 ? 1 : 0).replace(/\.0$/, '') + 'K'
  return (n / 1000000).toFixed(1) + 'M'
}

// The account used whenever an event has no author of its own
export function botAccount() {
  return { id: 'codx-junior', name: 'codx-junior', handle: 'codx-junior', avatar: null, verified: true, type: 'bot' }
}

export function meAccount(currentUser) {
  return {
    id: '__me',
    name: currentUser?.name || currentUser?.username || 'You',
    handle: currentUser?.username || 'you',
    avatar: currentUser?.avatar || null,
    verified: false,
    type: 'me'
  }
}

// Build the accounts referenced by the feed (current user + bot + users + projects)
export function buildAccounts({ currentUser = null, users = [], projects = [] } = {}) {
  const accounts = { __me: meAccount(currentUser), 'codx-junior': botAccount() }
  const userList = users || []
  const projectList = projects || []

  userList.forEach(u => {
    const id = u?.id || u?.username || u?.userName
    if (!id || accounts[id]) return
    accounts[id] = {
      id,
      name: u.name || u.username || u.userName || 'User',
      handle: u.username || u.userName || id,
      avatar: u.avatar || null,
      verified: false,
      type: 'user'
    }
  })

  projectList.forEach(p => {
    if (!p?.project_id || accounts[p.project_id]) return
    accounts[p.project_id] = {
      id: p.project_id,
      name: p.project_name,
      handle: p.project_name,
      avatar: p.project_icon || null,
      verified: true,
      type: 'project'
    }
  })

  return accounts
}

const EMPTY_COUNTS = { replies: 0, reposts: 0, likes: 0, views: 0 }

function postContext(chat, project) {
  if (chat?.board) return { label: chat.board, icon: 'fa-brands fa-trello' }
  if (project?.project_name) return { label: project.project_name, icon: 'fa-solid fa-cube' }
  return null
}

function postAttachment(chat) {
  if (!chat) return null
  if (chat.pr_view?.from_branch) {
    return {
      type: 'pr',
      title: chat.pr_view.title || chat.name,
      from: chat.pr_view.from_branch,
      to: chat.pr_view.to_branch
    }
  }
  if (chat.file_list?.length) {
    return { type: 'code', files: chat.file_list.map(path => ({ path })) }
  }
  if (chat.board || chat.column) {
    return { type: 'board', board: chat.board, to: chat.column || chat.status, task: chat.name }
  }
  return null
}

function postKind(chat) {
  if (chat?.pr_view?.from_branch) return 'pr'
  if (chat?.file_list?.length) return 'code'
  if (chat?.board || chat?.column) return 'kanban'
  return 'chat'
}

// Turn a chat (a project activity item) into a feed post
export function chatToPost(chat, project) {
  if (!chat) return null
  const messages = chat.messages || []
  const last = messages[messages.length - 1] || {}
  const isBot = last.role === 'assistant'
  const text = String(last.content || chat.name || 'Activity').replace(/\s+/g, ' ').trim()
  return {
    id: `chat-${project?.project_id || 'na'}-${chat.id || chat.doc_id || text.slice(0, 16)}`,
    kind: postKind(chat),
    authorId: isBot ? 'codx-junior' : (last.user || '__me'),
    createdAt: last.timestamp || last.created_at || chat.updated_at || chat.lastMessageAt || new Date().toISOString(),
    text: text.slice(0, 500),
    context: postContext(chat, project),
    attachment: postAttachment(chat),
    counts: { ...EMPTY_COUNTS, views: messages.length },
    chatId: chat.id,
    projectId: project?.project_id || null
  }
}

// Turn a live meet into a feed post
export function meetToPost(meet) {
  if (!meet?.meetId) return null
  return {
    id: `meet-${meet.meetId}`,
    kind: 'meet',
    authorId: meet.initiator || 'codx-junior',
    createdAt: meet.startedAt ? new Date(meet.startedAt).toISOString() : new Date().toISOString(),
    text: `Meeting started — ${meet.name || 'Meet'}`,
    context: { label: 'Meet', icon: 'fa-solid fa-video' },
    attachment: { type: 'meet', title: meet.name, participants: meet.participants || [] },
    counts: { ...EMPTY_COUNTS, views: (meet.participants || []).length },
    meetId: meet.meetId
  }
}

// Turn a UI notification into a feed post (used by the Notifications view)
export function notificationToPost(notification, index) {
  return {
    id: `notif-${index}-${notification?.ts || ''}`,
    kind: 'system',
    authorId: 'codx-junior',
    createdAt: new Date().toISOString(),
    text: notification?.text || '',
    context: null,
    attachment: null,
    type: notification?.type || 'info',
    counts: { ...EMPTY_COUNTS }
  }
}

// Assemble the feed from every source, newest first
export function buildPosts({ chats = [], meets = [], notifications = [], withNotifications = false } = {}) {
  const posts = []

  chats.forEach(({ chat, project }) => {
    const post = chatToPost(chat, project)
    if (post) posts.push(post)
  })

  meets.forEach(meet => {
    const post = meetToPost(meet)
    if (post) posts.push(post)
  })

  if (withNotifications) {
    notifications.forEach((n, ix) => posts.push(notificationToPost(n, ix)))
  }

  return posts.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
}

// Tab / kind / free-text filtering
export function filterPosts(posts, { tab = 'for-you', kind = 'all', query = '', following = [] } = {}) {
  let out = posts

  if (tab === 'following') {
    const set = new Set(following)
    out = out.filter(p => p.authorId === '__me' || p.authorId === 'codx-junior' || set.has(p.authorId))
  }

  if (kind && kind !== 'all') out = out.filter(p => p.kind === kind)

  const q = String(query || '').trim().toLowerCase()
  if (q) {
    out = out.filter(p =>
      String(p.text || '').toLowerCase().includes(q) ||
      String(p.context?.label || '').toLowerCase().includes(q))
  }

  return out
}

