<script setup>
import Login from './components/user/Login.vue'
import Toast from './components/Toast.vue'
import DesktopSidebar from './components/layout/DesktopSidebar.vue'
import MobileBottomBar from './components/layout/MobileBottomBar.vue'
import NewProject from './components/project/NewProject.vue'
import Wall from './components/wall/Wall.vue'
</script>

<template>
  <div class="w-full h-full relative bg-base-100" :data-theme="$ui.theme" v-if="$ui.uiReady">
    <Login v-if="isLogin" />

    <div class="h-full w-full flex" v-else :class="layoutClasses">
      <!-- Desktop Sidebar (Landscape on desktop) -->
      <DesktopSidebar
        v-if="isDesktopLandscape"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        @settings="openAccountSettings"
      />

      <!-- Mobile Sidebar Overlay (Mobile only, slides from left) -->
      <div
        v-if="isMobile && $ui.isSidebarExpanded"
        class="fixed inset-0 z-100 transition-opacity duration-200 md:hidden"
        @click="closeMobileSidebar"
      ></div>

      <!-- Mobile Sidebar (Slides from left on mobile) -->
      <DesktopSidebar
        v-if="isMobile"
        :user-name="$user?.username || 'User'"
        :user-subtitle="'Pro'"
        :is-mobile="true"
        class="z-150"
        @close="closeMobileSidebar"
        @settings="openAccountSettings"
      />

      <!-- Main Content with Router (Flex context for scrollable children) -->
      <div class="grow flex flex-col min-h-0 min-w-0">
        <!-- The Activity Wall is the home screen for the mobile view. Every
             other screen keeps coming from the router; only the home route on
             mobile is swapped for the wall. -->
        <Wall v-if="isMobileHome" />
        <RouterView v-else />
      </div>

      <!-- Mobile Bottom Bar (Portrait on mobile) -->
      <MobileBottomBar
        v-if="showMobileBottomBar"
        :user-name="$user?.username || 'User'"
        @show-menu="openMobileSidebar"
      />

      <!-- Toast Notifications -->
      <Toast ref="toastComponent" />

      <!-- Global "New project" modal — opened from any launcher
           (sidebar AppsSection, MainMenuItems, WindowsMenuItems, QuickBar)
           through the ui store flag `newProject`. -->
      <modal
        v-if="$ui.newProject"
        close="true"
        @close="$ui.showNewProject(false)"
      >
        <NewProject />
      </modal>
    </div>
  </div>

  <div class="flex flex-col items-center justify-center w-full h-full font-2xl px-4 py-2" v-else>
    <div class="animate-pulse font-mono text-green-600">Wake up, codx-junior...</div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      pendingProjectSwitch: null,
      windowWidth: 0,
      windowHeight: 0
    }
  },
  computed: {
    isLogin() {
      return !this.$user
    },
    isDesktop() {
      return this.windowWidth >= 768
    },
    isMobile() {
      return this.windowWidth < 768
    },
    isLandscape() {
      return this.windowWidth > this.windowHeight
    },
    isPortrait() {
      return this.windowHeight > this.windowWidth
    },
    isDesktopLandscape() {
      return this.isDesktop && this.isLandscape
    },
    isMobileLandscape() {
      return this.isMobile && this.isLandscape
    },
    isMobilePortrait() {
      return this.isMobile && this.isPortrait
    },
    // The Activity Wall is registered as the home screen for the mobile view.
    // Uses the ui store's `isMobile` flag (the same source of truth that drives
    // MobileBottomBar and the mobile sidebar), and covers both the scoped home
    // route ("home") and the unscoped bootstrap route ("root").
    isMobileHome() {
      return this.$ui.isMobile && ['home', 'root'].includes(this.$route.name)
    },
    layoutClasses() {
      if (this.isMobilePortrait) {
        return 'flex-col'
      }
      return 'flex-row'
    },
    infoNotifications() {
      return this.$ui.notifications.filter(n => n.type !== 'error')
    },
    errorNotifications() {
      return this.$ui.notifications.filter(n => n.type === 'error')
    },
    showMobileBottomBar() {
      const navigation = this.$storex.$router.$navigation
      // Hide the bottom bar inside a chat or the Meet tool, which take over
      // the full screen (the bar would otherwise cover their content).
      return !navigation.getChatId() && !navigation.isMeetView && this.$ui.isMobile
    }
  },
  created() {
    // Resolve the viewport before the first paint so the mobile sidebar starts
    // collapsed (the ui store default is expanded for desktop).
    this.updateDimensions()
    if (this.isMobile) {
      this.closeMobileSidebar()
    }
  },
  watch: {
    '$ui.projectLoadingState': {
      handler(newState) {
        if (!newState || !newState.isLoading) return
        const overlay = this.$refs.loadingOverlay
        if (overlay && typeof overlay.startLoading === 'function') {
          overlay.startLoading(newState.projectName)
        }
      },
      deep: true
    },
    '$route'() {
      // Mobile sidebar is an overlay: close it when navigating away.
      if (this.isMobile) {
        this.closeMobileSidebar()
      }
    }
  },
  mounted() {
    this.updateDimensions()
    window.addEventListener('resize', this.updateDimensions)
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateDimensions)
  },
  methods: {
    updateDimensions() {
      this.windowWidth = window.innerWidth
      this.windowHeight = window.innerHeight
    },
    // The mobile sidebar open/close state is owned by the ui store
    // (`sidebarCollapsed`) instead of a local flag, so the sidebar and its
    // backdrop stay in sync through a single source of truth.
    openMobileSidebar() {
      this.$storex.ui.expandSidebar()
    },
    closeMobileSidebar() {
      this.$storex.ui.collapseSidebar()
    },
    retryProjectLoad() {
      if (this.pendingProjectSwitch) {
        this.$storex.projects.activeProjectChanged(this.pendingProjectSwitch)
      }
    },
    cancelProjectLoad() {
      this.pendingProjectSwitch = null
      this.$storex.ui.setProjectLoadingState({ isLoading: false })
    },
    openAccountSettings() {
      this.$emit('settings')
    }
  }
}
</script>
