        class="textarea textarea-ghost w-full text-base leading-relaxed resize-none focus:outline-none"
        aria-label="Compose update"
      ></textarea>

      <div class="flex items-center justify-end gap-3 mt-1 pt-1 border-t border-base-content/10">
        <span class="text-xs" :class="overLimit ? 'text-error' : 'text-base-content/50'">
          {{ text.length }}/{{ max }}
        </span>
        <button class="btn btn-primary btn-sm" :disabled="!canSubmit || submitting" @click="submit">
          <span v-if="submitting" class="loading loading-spinner loading-xs"></span>
          {{ replyTo ? 'Reply' : 'Post' }}
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    me: { type: Object, required: true },
    replyTo: { type: Object, default: null },
    // Resolved author account of the post being replied to (posts only carry
    // `authorId`, so the parent resolves the handle and passes it in).
    replyAuthor: { type: Object, default: null },
    submitting: { type: Boolean, default: false }
  },
  emits: ['submit', 'cancel-reply'],
  data() {
    return {
      text: '',
      max: 280
    }
  },
  computed: {
    overLimit() {
      return this.text.length > this.max
    },
    canSubmit() {
      return this.text.trim().length > 0 && !this.overLimit
    },
    replyHandle() {
      return this.replyAuthor?.handle || this.replyTo?.author?.handle || 'unknown'
    }
  },
  methods: {
    submit() {
      if (!this.canSubmit || this.submitting) return
      this.$emit('submit', this.text.trim())
      this.text = ''
    }
  }
}
</script>
